"use client"

import * as React from "react"

import { Icon } from "@/components/ui/icon"
import { cn } from "@/lib/utils"

import { useAssistant, type ContextChip } from "./assistant-context"

/**
 * The two components of the attach gesture: the menu a right-click opens,
 * and the inline "Ask AI" a row reveals on hover. The hook that positions
 * the menu lives in use-attach-menu.ts.
 */
export function AttachMenu({
  menu,
  onClose,
}: {
  menu: { x: number; y: number; chip: ContextChip } | null
  onClose: () => void
}) {
  const { explain, addChip, setMode } = useAssistant()
  const ref = React.useRef<HTMLDivElement | null>(null)

  React.useEffect(() => {
    if (!menu) return
    // A pointerdown INSIDE the menu is the first half of choosing an item.
    // Dismissing on it unmounts the menu before the click can land, which is
    // why both verbs were unreachable: the gesture that opens the item is the
    // same gesture that was closing it.
    const dismiss = (e: Event) => {
      if (ref.current?.contains(e.target as Node)) return
      onClose()
    }
    // any click outside, scroll, or Escape closes it — a context menu that
    // survives the next interaction is a modal nobody asked for
    window.addEventListener("pointerdown", dismiss)
    window.addEventListener("scroll", dismiss, true)
    const key = (e: KeyboardEvent) => e.key === "Escape" && onClose()
    window.addEventListener("keydown", key)
    return () => {
      window.removeEventListener("pointerdown", dismiss)
      window.removeEventListener("scroll", dismiss, true)
      window.removeEventListener("keydown", key)
    }
  }, [menu, onClose])

  if (!menu) return null

  const item =
    "flex w-full items-center gap-2 rounded-lg px-2 py-1.5 text-start text-sm hover:bg-(--glass-wash)"

  return (
    <div
      ref={ref}
      role="menu"
      // clamped so a right-click near an edge still lands on screen
      style={{
        left: Math.min(menu.x, window.innerWidth - 220),
        top: Math.min(menu.y, window.innerHeight - 110),
      }}
      className="ambient-glass border-(--glass-border) fixed z-50 w-52 rounded-xl border p-1 shadow-lg"
    >
      <div className="text-muted-foreground truncate px-2 py-1 font-mono text-xs">
        {menu.chip.label}
      </div>
      <button
        type="button"
        role="menuitem"
        className={item}
        onClick={() => {
          explain(menu.chip)
          onClose()
        }}
      >
        <Icon name="sparkles" size={13} />
        Explain with AI
      </button>
      <button
        type="button"
        role="menuitem"
        className={cn(item, "text-muted-foreground")}
        onClick={() => {
          addChip(menu.chip)
          setMode("spotlight")
          onClose()
        }}
      >
        <Icon name="plus" size={13} />
        Add to chat context
      </button>
    </div>
  )
}

/**
 * The inline entry point: a quiet "Ask AI" that appears on a row's hover.
 *
 * Putting it IN the row rather than in a toolbar is the whole point — the
 * question is asked where the thing is, so the user never has to describe
 * what they were looking at.
 *
 * IT FLOATS RATHER THAN SITTING IN FLOW. An affordance that appears on hover
 * must not resize the thing being hovered: in flow it made every row grow a
 * few pixels the moment the pointer landed, which reads as the list flinching.
 * Positioned absolutely, revealing it costs no layout at all.
 *
 * The row must therefore be `relative group/row`.
 */
export function AskAI({
  chip,
  prompt,
  className,
}: {
  chip: ContextChip
  /** Overrides the default "Explain …" question. */
  prompt?: string
  className?: string
}) {
  const { addChip, seedPrompt, setMode } = useAssistant()
  return (
    <button
      type="button"
      onClick={(e) => {
        e.stopPropagation()
        addChip(chip)
        seedPrompt(prompt ?? `Explain ${chip.label}`, true)
        setMode("panel")
      }}
      className={cn(
        "border-border bg-card text-muted-foreground hover:text-foreground absolute end-2 top-1/2 hidden shrink-0 -translate-y-1/2 items-center gap-1 rounded-md border px-1.5 py-0.5 text-xs group-hover/row:inline-flex",
        className
      )}
    >
      <Icon name="sparkles" size={11} />
      Ask AI
    </button>
  )
}

import type { ContextChip } from "./assistant-context"
import type { KitBlock, KitResponse } from "./response-kit"

/**
 * THE MODEL SEAM — now a SCENARIO ROUTER.
 *
 * Everything downstream of this function is real: the streaming, the staged
 * evidence, the states, the objects an answer is made of. Only the judgement
 * is canned. Wiring a model in replaces THIS FILE and nothing else — it emits
 * the same `KitResponse` grammar, and every surface keeps rendering it.
 *
 * What the router demonstrates is the thesis of the dev-tool simulation:
 * AN ANSWER'S SHAPE FOLLOWS ITS INTENT AND ITS CONTEXT, and scenarios CHAIN.
 * "Fix this" earns a diff to review; "run it" earns a terminal and, when it
 * fails, a failure with recovery follow-ups; "fix automatically" continues
 * that same workflow rather than opening a new conversation. The follow-ups
 * are the seams between scenarios — picking one hands the next intent back
 * through this router, which is how a few minutes of natural use walks the
 * whole vocabulary without ever feeling like a component tour.
 */

type Intent =
  | "fix-all"
  | "fix-auto"
  | "api-error"
  | "stream-error"
  | "db-error"
  | "threadlist-error"
  | "figma-sync"
  | "token-change"
  | "make-component"
  | "compact"
  | "generate-ui"
  | "research"
  | "refactor"
  | "run"
  | "tests"
  | "usages"
  | "fix"
  | "explain"
  | "code"
  | "generic"

/** Order matters: the first pattern that matches wins. */
function detectIntent(q: string, codeChip: boolean): Intent {
  const t = q.toLowerCase()
  // before every single-problem pattern: "fix everything" is a different
  // request from "fix this", and the specific patterns would swallow it
  if (/fix (all|everything|every problem|them all)|clear the (problem|inventory|board)|work through (all|the) problem/.test(t))
    return "fix-all"
  if (/fix (it )?automatically|apply the fix/.test(t)) return "fix-auto"
  if (/500|unhandled|rejection|api\/messages|post .*(fail|500)/.test(t))
    return "api-error"
  if (/stream .*(drop|dies|disconnect)|sse|heartbeat|30 seconds/.test(t))
    return "stream-error"
  if (/slow|n\+1|drafts endpoint|explain analyze|\bquery\b/.test(t))
    return "db-error"
  if (/re-?render|render loop|thread list.*loop|flicker|key warning/.test(t))
    return "threadlist-error"
  if (/figma/.test(t)) return "figma-sync"
  if (/radius|token|spacing unit|gray family|accent/.test(t)) return "token-change"
  if (/make this a component|extract .*component/.test(t)) return "make-component"
  if (/more compact|onboarding empty state/.test(t)) return "compact"
  if (/empty state|add .*state to this page|compose .*from/.test(t)) return "generate-ui"
  if (/recommended|best (way|approach)|how should|current react architecture/.test(t))
    return "research"
  if (/implement that|refactor|reusable|move .*(out|into|persistence)/.test(t))
    return "refactor"
  if (/\brun\b|check whether|verify the fix/.test(t)) return "run"
  if (/add tests|regression test|test suite/.test(t)) return "tests"
  if (/where .*used|find usages|usages/.test(t)) return "usages"
  if (/fix|wrong|vanish|broken|bug/.test(t)) return "fix"
  if (/what is|what does|explain|doing\??$|data flow/.test(t)) return "explain"
  if (codeChip) return "code"
  return "generic"
}

